103			s.FederatedResolver.Authorize != nil {
104			// A dynamic authorization callback must be asked on every traversal.
105			run(s)
106			return
107		}
108		// Fallback retains its existing clock semantics, including a live clock.
109		s = s.atReviewTime(s.reviewClock())
110		m := &doctorCloseoutMemo{view: s.reviewView, at: s.reviewClock(), entries: map[string]doctorCloseoutEntry{}}
111		s.doctorCloseoutMemo = m
