120	func (s Store) doctorMemoClosedByReceipt(ref string) (bool, error) {
121		m := s.doctorCloseoutMemo
122		if m == nil || s.reviewView != m.view || !m.view.boundTo(s) ||
123			s.reviewTime == nil || !s.reviewTime.Equal(m.at) || s.indexMaterial || s.planWithoutCloseoutGate ||
124			s.FederatedResolver == nil || s.FederatedResolver.Authorize != nil {
125			// A child under an incompatible context cannot leave a reusable parent.
126			s.closeoutTrace.visit("", true)
127			return s.computeClosedByReceipt(ref)
128		}
129		readView, _ := governanceReadViewFromFiles(s.fsys())
130		if readView == nil {
131			s.closeoutTrace.visit("", true)
132			return s.computeClosedByReceipt(ref)
133		}
134		readView.mu.Lock()
135		finalized := readView.closed
136		readView.mu.Unlock()
137		if finalized {
138			s.closeoutTrace.visit("", true)
139			return s.computeClosedByReceipt(ref)
140		}
141		key := m.view.root + "\x00" + m.view.project + "\x00" + ref
142		m.mu.Lock()
143		if m.closed {
144			m.mu.Unlock()
145			return s.computeClosedByReceipt(ref)
146		}
147		entry, hit := m.entries[key]
148		if hit {
149			for _, ancestor := range s.closeoutChain {
150				for _, visited := range entry.visited {
151					if ancestor == visited {
152						hit = false
153						break
154					}
155				}
156				if !hit {
157					break
158				}
159			}
160		}
161		m.mu.Unlock()
162		if hit {
163			s.closeoutTrace.merge(entry.visited, false)
164			return true, nil
165		}
166		parent := s.closeoutTrace
167		trace := &doctorCloseoutTrace{visited: map[string]bool{}}
168		trace.visit(ref, false)
169		s.closeoutTrace = trace
170		// Never hold a memo/trace lock (or Once) over recursive verification.
171		if m.onCompute != nil {
172			m.onCompute(ref)
173		}
174		closed, err := s.computeClosedByReceipt(ref)
175		visited, cut := trace.snapshot()
176		parent.merge(visited, cut || err != nil)
177		if closed && err == nil && !cut {
178			m.mu.Lock()
